window.addEventListener('load', function() {
    const audio = document.getElementById('myAudio');
    const musicIcon = document.getElementById('musicIcon');
    if (!audio || !musicIcon) return;

    let isPlaying = false;
    let musicStarted = false;

    // ≡ƒƒó H├ám bß║¡t nhß║íc
    function startMusic() {
        if (musicStarted) return;
        musicStarted = true;

        audio.play().then(() => {
            isPlaying = true;
            musicIcon.classList.add('playing');
            musicIcon.classList.remove('paused');
        }).catch(err => {
            console.log("ΓÜá∩╕Å Autoplay bß╗ï chß║╖n:", err);
        });
    }

    // ≡ƒÄº Cho ph├⌐p bß║¡t/tß║»t thß╗º c├┤ng khi click v├áo icon
    musicIcon.addEventListener('click', function(e) {
        e.stopPropagation();
        if (isPlaying) {
            audio.pause();
            isPlaying = false;
            musicIcon.classList.remove('playing');
            musicIcon.classList.add('paused');
        } else {
            audio.play().then(() => {
                isPlaying = true;
                musicIcon.classList.add('playing');
                musicIcon.classList.remove('paused');
            }).catch(err => {});
        }
    });

    // ≡ƒîÇ Khi nhß║íc kß║┐t th├║c, tß╗▒ dß╗½ng v├á ─æß╗òi trß║íng th├íi icon
    audio.addEventListener('ended', () => {
        isPlaying = false;
        musicIcon.classList.remove('playing');
        musicIcon.classList.add('paused');
    });

    // Γ£¿ Ph├ít nhß║íc khi c├│ h├ánh ─æß╗Öng ─æß║ºu ti├¬n: cuß╗Ön, chß║ím hoß║╖c vuß╗æt
    ['scroll', 'touchstart', 'touchmove', 'wheel'].forEach(evt => {
        window.addEventListener(evt, startMusic, { once: true });
    });
});

